import React, { useEffect, useState } from "react";

export default function Candidates() {
  const [candidates, setCandidates] = useState([]);

  useEffect(() => {
    // Fetch approved candidates from backend
    fetch("/api/candidates")
      .then((res) => res.json())
      .then((data) => setCandidates(data))
      .catch((err) => console.error("Failed to load candidates:", err));
  }, []);

  return (
    <div className="min-h-screen bg-gray-50 px-6 py-10">
      {/* Header */}
      <div className="max-w-6xl mx-auto mb-8 text-center">
        <h1 className="text-3xl font-bold text-gray-800 mb-2">Election Candidates</h1>
        <p className="text-gray-600 text-lg">
          Browse the list of approved candidates before casting your vote.
        </p>
      </div>

      {/* Candidate list */}
      <div className="max-w-6xl mx-auto grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {candidates.length > 0 ? (
          candidates.map((c) => (
            <div
              key={c.id}
              className="bg-white shadow-md rounded-2xl p-6 border border-gray-200 hover:shadow-lg transition"
            >
              {/* Candidate photo (optional placeholder) */}
              <div className="w-24 h-24 mx-auto mb-4 rounded-full bg-gray-100 flex items-center justify-center text-gray-500 text-2xl font-bold">
                {c.name.charAt(0)}
              </div>

              {/* Candidate info */}
              <h2 className="text-xl font-semibold text-gray-800 text-center">
                {c.name}
              </h2>
              <p className="text-gray-600 text-center mb-3">{c.position}</p>

              <p className="text-gray-500 text-sm line-clamp-3">
                {c.manifesto || "No manifesto provided."}
              </p>
            </div>
          ))
        ) : (
          <div className="col-span-full text-center text-gray-500">
            No candidates available.
          </div>
        )}
      </div>
    </div>
  );
}
